"""Audio fixtures for the S2a tests: every file is generated by ffmpeg inside the test run.

No binary fixture is checked in. A session-scoped temp directory holds sine tones in each
accepted container (with title / artist / comment tags and an attached cover picture, which ingest
must strip), silence, a full-scale square wave, a too-short file, an MP4 with a video stream and an
Ogg/Opus file (refused). ``require_ffmpeg`` fails in CI and skips locally, like the video tests.
"""

from __future__ import annotations

import json
import os
import shutil
import subprocess
from dataclasses import dataclass
from typing import TYPE_CHECKING

import pytest

if TYPE_CHECKING:
    from collections.abc import Iterator
    from pathlib import Path

FFMPEG = shutil.which("ffmpeg")
FFPROBE = shutil.which("ffprobe")

SECRET_TAGS = {
    "title": "SECRET_TITLE_VALUE",
    "artist": "SECRET_ARTIST_VALUE",
    "comment": "SECRET_COMMENT_VALUE",
}
"""Tag values the stored file must not contain: also asserted absent from the bytes and the logs."""

# container -> (file extension, ffmpeg audio encoder)
CONTAINERS: dict[str, tuple[str, str]] = {
    "mp3": ("mp3", "libmp3lame"),
    "m4a": ("m4a", "aac"),
    "wav": ("wav", "pcm_s16le"),
    "flac": ("flac", "flac"),
}


def require_ffmpeg() -> str:
    """The ffmpeg path; a missing binary fails in CI and skips locally."""
    if FFMPEG is None or FFPROBE is None:
        if os.environ.get("CI"):
            pytest.fail("ffmpeg is required for the audio ingest tests in CI")
        pytest.skip("ffmpeg is unavailable locally")
    return FFMPEG


def run(args: list[str]) -> subprocess.CompletedProcess[bytes]:
    """Run a media command, failing the test with ffmpeg's own message when it fails."""
    result = subprocess.run(args, capture_output=True, check=False)  # noqa: S603
    if result.returncode != 0:
        pytest.fail(f"{args[0]} failed: {result.stderr.decode(errors='replace')[-600:]}")
    return result


def probe(path: Path) -> dict[str, object]:
    """``ffprobe`` of ``path`` with every tag, stream and disposition (for the assertions)."""
    require_ffmpeg()
    out = run(
        [
            FFPROBE or "ffprobe",
            "-v",
            "error",
            "-show_streams",
            "-show_format",
            "-of",
            "json",
            str(path),
        ]
    ).stdout
    decoded: dict[str, object] = json.loads(out)
    return decoded


def stream_md5(path: Path) -> str:
    """MD5 of the first audio stream's packets (``-c copy``): equal means bit-identical audio."""
    out = run(
        [
            require_ffmpeg(),
            "-v",
            "error",
            "-i",
            str(path),
            "-map",
            "0:a:0",
            "-c",
            "copy",
            "-f",
            "streamhash",
            "-hash",
            "md5",
            "-",
        ]
    ).stdout.decode()
    return out.strip()


def user_tags(info: dict[str, object]) -> dict[str, str]:
    """Every tag of a probe (format and streams) that is not a structural brand of the container."""
    tags: dict[str, str] = {}
    containers: list[dict[str, object]] = []
    fmt = info.get("format")
    if isinstance(fmt, dict):
        containers.append(fmt)
    streams = info.get("streams")
    if isinstance(streams, list):
        containers.extend(s for s in streams if isinstance(s, dict))
    for entry in containers:
        found = entry.get("tags")
        if isinstance(found, dict):
            tags.update({str(k).lower(): str(v) for k, v in found.items()})
    structural = {
        "major_brand",
        "minor_version",
        "compatible_brands",
        "handler_name",
        "vendor_id",
        "language",  # the mov muxer writes ``und`` for a track with no language
    }
    return {k: v for k, v in tags.items() if k not in structural}


def has_attached_picture(info: dict[str, object]) -> bool:
    streams = info.get("streams")
    if not isinstance(streams, list):
        return False
    return any(
        isinstance(s, dict)
        and s.get("codec_type") == "video"
        and isinstance(s.get("disposition"), dict)
        and s["disposition"].get("attached_pic")
        for s in streams
    )


def _tone(path: Path, container: str, *, seconds: float, with_tags: bool) -> None:
    _, codec = CONTAINERS[container]
    ffmpeg = require_ffmpeg()
    cover = path.parent / "cover.png"
    if not cover.exists():
        run(
            [
                ffmpeg,
                "-v",
                "error",
                "-y",
                "-f",
                "lavfi",
                "-i",
                "color=c=red:s=64x64",
                "-frames:v",
                "1",
                str(cover),
            ]
        )
    args = [
        ffmpeg,
        "-v",
        "error",
        "-y",
        "-f",
        "lavfi",
        "-i",
        f"sine=frequency=440:duration={seconds}",
    ]
    with_picture = with_tags and container != "wav"  # WAV cannot carry a picture
    if with_picture:
        args += ["-i", str(cover), "-map", "0:a", "-map", "1:v", "-c:v", "png"]
        args += ["-disposition:v", "attached_pic"]
    args += ["-c:a", codec]
    if with_tags:
        for key, value in SECRET_TAGS.items():
            args += ["-metadata", f"{key}={value}"]
    run([*args, str(path)])


@dataclass(frozen=True)
class AudioFixtures:
    """Paths of the generated files."""

    root: Path

    def tone(self, container: str) -> Path:
        """A 6 s sine with tags and (except WAV) an attached cover picture."""
        return self.root / f"tone.{CONTAINERS[container][0]}"

    @property
    def silence(self) -> Path:
        return self.root / "silence.wav"

    @property
    def square(self) -> Path:
        return self.root / "square.wav"

    @property
    def short(self) -> Path:
        """2 s: under the 5 s minimum."""
        return self.root / "short.wav"

    @property
    def video_mp4(self) -> Path:
        """An MP4 with a real video stream and an audio stream."""
        return self.root / "with_video.mp4"

    @property
    def ogg_opus(self) -> Path:
        return self.root / "opus.ogg"

    @property
    def pcm_float(self) -> Path:
        """A WAV with float PCM: a valid container, a codec outside the accepted four."""
        return self.root / "float.wav"

    @property
    def picture_only(self) -> Path:
        """A PNG: not audio at all."""
        return self.root / "cover.png"


def build_audio_fixtures(root: Path) -> AudioFixtures:
    """Generate every fixture file into ``root``."""
    ffmpeg = require_ffmpeg()
    fixtures = AudioFixtures(root)
    for container in CONTAINERS:
        _tone(fixtures.tone(container), container, seconds=6, with_tags=True)
    run(
        [
            ffmpeg,
            "-v",
            "error",
            "-y",
            "-f",
            "lavfi",
            "-i",
            "anullsrc=r=44100:cl=mono",
            "-t",
            "6",
            "-c:a",
            "pcm_s16le",
            str(fixtures.silence),
        ]
    )
    run(
        [
            ffmpeg,
            "-v",
            "error",
            "-y",
            "-f",
            "lavfi",
            "-i",
            "aevalsrc=sgn(sin(2*PI*441*t)):s=44100:d=6",
            "-c:a",
            "pcm_s16le",
            str(fixtures.square),
        ]
    )
    run(
        [
            ffmpeg,
            "-v",
            "error",
            "-y",
            "-f",
            "lavfi",
            "-i",
            "sine=frequency=440:duration=2",
            "-c:a",
            "pcm_s16le",
            str(fixtures.short),
        ]
    )
    run(
        [
            ffmpeg,
            "-v",
            "error",
            "-y",
            "-f",
            "lavfi",
            "-i",
            "color=c=blue:s=64x64:d=6",
            "-f",
            "lavfi",
            "-i",
            "sine=frequency=440:duration=6",
            "-c:v",
            "libx264",
            "-pix_fmt",
            "yuv420p",
            "-c:a",
            "aac",
            "-shortest",
            str(fixtures.video_mp4),
        ]
    )
    run(
        [
            ffmpeg,
            "-v",
            "error",
            "-y",
            "-f",
            "lavfi",
            "-i",
            "sine=frequency=440:duration=6",
            "-c:a",
            "libopus",
            str(fixtures.ogg_opus),
        ]
    )
    run(
        [
            ffmpeg,
            "-v",
            "error",
            "-y",
            "-f",
            "lavfi",
            "-i",
            "sine=frequency=440:duration=6",
            "-c:a",
            "pcm_f32le",
            str(fixtures.pcm_float),
        ]
    )
    return fixtures


@pytest.fixture(scope="session")
def audio_files(tmp_path_factory: pytest.TempPathFactory) -> Iterator[AudioFixtures]:
    """The generated audio files, built once per test session."""
    yield build_audio_fixtures(tmp_path_factory.mktemp("audio-fixtures"))
